-- New independent job only when pg_cron is already available. No existing job is modified.
DO $$ BEGIN
 IF to_regprocedure('cron.schedule(text,text,text)') IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='suizamente-mejoras-avisos') THEN
   PERFORM cron.schedule('suizamente-mejoras-avisos','* * * * *','SELECT public.suizamente_mejoras_avisos()');
  END IF;
 END IF;
END $$;
NOTIFY pgrst,'reload schema';
COMMIT;
